let state=readSave(storage),modal=null,returnTo=null,worldInfo={},lastSave=0,toastTimer,audioCtx,selectedElement=29,tabletControls=null,allInputs=null,streetPoint=null,streetMessage='',streetStamp='',practiceId=null;
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const colors={alkali:'#694f37',alkaline:'#655b34',transition:'#285264','post-transition':'#3d5162',metalloid:'#4b5269',nonmetal:'#2e6359',halogen:'#5f4663',noble:'#5a506d',lanthanide:'#4e5157',actinide:'#615150',unknown:'#38484f'};
const current=()=>MISSIONS.find(m=>m.id===state.active);const next=()=>MISSIONS.find(m=>!state.completed.includes(m.id));
const callbacks={onQuality:q=>toast(`Graphics set to ${q==='low'?'Battery saver':'Balanced'} for smoother play. Change it in Pause.`),onContextLost:()=>openModal('recovery','<h2>Graphics paused</h2><p>Your iPad paused the 3D view. Reload to restore your saved investigation.</p><button data-act="reload">Reload game</button>'),onWorldAction:id=>enterStreetPoint(id),onChange:info=>{if(info.district&&worldInfo.district&&info.district!==worldInfo.district&&state.started&&!modal)districtPop(info.district);worldInfo=info;state.walked=Math.max(state.walked,info.walked||0);state.driven=Math.max(state.driven,info.driven||0);checkTutorial();updateHUD();renderStreet();updateEngineSound();if(Date.now()-lastSave>7000&&state.started){save();lastSave=Date.now()}},onInteract:id=>interactStation(id),onDiscover:id=>{if(!state.discoveries.includes(id)){state.discoveries.push(id);record('City discovery',`Found ${id}. Exploration progress is separate from chemistry.`);toast('Discovery recorded in your notebook.');save()}}};
let world;try{if(new URLSearchParams(location.search).has('2d'))throw new Error('2D view requested');world=new CityWorld($('#world'),$('#minimap'),callbacks)}catch(error){console.warn('3D unavailable; using overhead view.',error);const old=$('#world'),replacement=old.cloneNode();old.replaceWith(replacement);world=new FlatWorld(replacement,$('#minimap'),callbacks)}
