function save(){state.position=world.getState();const ok=writeSave(storage,state);$('#systems').title=ok?'Progress saved on this browser':'Storage unavailable: progress lasts for this session.';return ok}
function touchUI(){const t=state.settings.touch;if(t===true||t===false)return t;return matchMedia('(pointer:coarse)').matches||(navigator.maxTouchPoints||0)>0}
