let bannerTimer,popTimer;
function banner(kicker,title,sub='',cls=''){const b=$('#banner');$('#banner-kicker').textContent=kicker;$('#banner-title').textContent=title;$('#banner-sub').textContent=sub;b.className='banner '+cls;void b.offsetWidth;clearTimeout(bannerTimer);bannerTimer=setTimeout(()=>b.classList.add('hidden'),3300)}
function districtPop(name){const d=$('#district-pop');d.textContent=name;d.classList.remove('hidden');d.style.animation='none';void d.offsetWidth;d.style.animation='';clearTimeout(popTimer);popTimer=setTimeout(()=>d.classList.add('hidden'),3100)}
function beep(kind='tap'){if(!state.settings.volume)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=kind==='success'?660:kind==='wrong'?180:420;gain.gain.setValueAtTime(state.settings.volume*.12,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.2);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.21)}catch{}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4000)}
function record(title,text){state.journal.push({title,text});if(state.journal.length>70)state.journal.shift()}
function openModal(type,html,cls=''){modal=type;clearInputs();$('#modal-root').innerHTML=`<div class="scrim ${type==='title'?'title-screen':''}"><section role="dialog" aria-modal="true" aria-label="${esc(type)}" class="dialog ${cls}" tabindex="-1">${html}</section></div>`;sync();requestAnimationFrame(()=>$('.dialog')?.focus({preventScroll:true}))}
