const closeButton=()=>'<button class="close" data-act="close" aria-label="Close panel">×</button>';
const footer=()=>'<div class="tool-row"><button data-act="mission-table">Periodic table</button><button data-act="hint">Get a hint</button><button data-act="close">Return to city</button></div><div id="hint" class="hint" aria-live="polite"></div><div id="feedback" class="feedback" aria-live="polite"></div>';
function feedback(text,wrong=false){const el=$('#feedback');if(el){el.textContent=text;el.className='feedback'+(wrong?' wrong':'')}if(wrong){state.revisions++;record('Prediction revised',text);beep('wrong')}else beep('success');save()}
function title(){openModal('title',`<span class="title-chip">A CITY BUILT ON DISCOVERY</span><h1>ELEMENT<span>CITY.</span></h1><div class="subtitle">Periodic Pursuit</div><p class="lead">The city’s systems are failing. The evidence is elemental. Borrow a ride, follow the clues, and bring the lights back.</p><div class="actions"><button class="primary" data-act="start">${state.started?'Continue investigation':'Join the response team'}</button><button data-act="guide">How to play</button></div><p class="byline">AN ORIGINAL CHEMISTRY ADVENTURE · NO ACCOUNT NEEDED<br>Keyboard + touch · Progress stays in this browser</p>`,'title-card')}
function start(){const first=!state.started;state.started=true;closeModal();if(state.active==='power'&&state.step>0)world.focusWorkshop?.();if(first){state.tutorial=0;record('Welcome to Element City','You joined the student science response team. Use the periodic table as a tool; revision is part of investigation.');tutorialIntro()}sync();save()}
function tutorialIntro(){const touch=touchUI();openModal('tutorial',`${closeButton()}<div class="eyebrow">WELCOME / RESPONSE TEAM HQ</div><h2>Let’s get you moving.</h2><div class="portrait">IP</div><div class="speaker">Dr. Imani Park · Team lead</div><p class="quote">“Welcome, investigator. Someone has mixed up the city’s materials. Your job is to ask better questions than our very confused equipment.”</p><div class="help-grid"><div><b>1 · Walk</b><p>${touch?'Put your left thumb anywhere in the lower-left of the screen and slide. A small push walks; a big push jogs.':'WASD or arrow keys. Hold Shift to jog faster.'}</p></div><div><b>2 · Look around</b><p>${touch?'Drag anywhere else on the city with your right thumb. The camera eases back behind you.':'Drag the city with the mouse. R recenters the camera.'}</p></div><div><b>3 · Borrow the fleet car</b><p>${touch?'Walk to the white car and tap Enter fleet car. Hold GAS with your right thumb and steer with your left. BRAKE stops, then reverses.':'Walk to the white car and press E. W accelerates, A/D steer, Space brakes, S reverses.'}</p></div><div><b>4 · Follow the gold route</b><p>The gold line on the street and radar leads to your next contact. Park, step out, and interact at the marker.</p></div></div><p class="small-note">Fleet cars are authorized city vehicles. Traffic and pedestrians always yield. Nothing is timed. If stuck: Pause → Return to HQ. All chemistry tests are virtual.</p><div class="actions"><button class="primary" data-act="close">Step into the city</button><button data-act="skip-tutorial">Skip the driving lesson</button></div>`)}
function checkTutorial(){if(!state.started||state.tutorial>=3)return;let changed=false;if(state.tutorial===0&&state.walked>70){state.tutorial=1;changed=true;toast(matchMedia('(pointer:coarse)').matches?'Nice. Walk to the white fleet car and tap Enter fleet car.':'Nice. Walk to the white fleet car and press E.')}if(state.tutorial===1&&worldInfo.inVehicle){state.tutorial=2;changed=true;toast('Fleet car authorized. GAS / W accelerates; steer left and right.')}if(state.tutorial===2&&state.driven>180){state.tutorial=3;changed=true;toast('Nice driving. Follow the gold route to Maya.');banner('INVESTIGATION 01','Power to the Block','Follow the gold route')}if(changed)save()}
function updateHUD(){const visible=state.started&&modal!=='title',touch=touchUI();
document.body.classList.toggle('touch-mode',touch);document.body.classList.toggle('driving',!!worldInfo.inVehicle&&visible);document.body.classList.toggle('button-controls',state.settings.controlStyle==='buttons');document.body.style.setProperty('--control-scale',state.settings.controlSize||1);
['hud','objective','tools','context'].forEach(id=>$('#'+id).classList.toggle('hidden',!visible));$('#touch').classList.toggle('hidden',!visible||!touch);
$('#speedo').classList.toggle('hidden',!visible||!worldInfo.inVehicle);
if(worldInfo.inVehicle){$('#speed-value').textContent=String(toKmh(worldInfo.speed||0));$('#gear').textContent=(worldInfo.speed||0)<-1?'R':Math.abs(worldInfo.speed||0)<1?'N':'D'}
$('#district').textContent=(worldInfo.district||'Research quarter').toUpperCase();
$('#rep').textContent=`${repScore()} REP`;
$('#ride').textContent=worldInfo.inVehicle?'CITY FLEET':'ON FOOT';
$('#vehicle').textContent=worldInfo.inVehicle?'E · Exit car':'E · Enter fleet car';
$('#vehicle').disabled=!worldInfo.inVehicle&&!worldInfo.vehicleNearby;
const work=worldInfo.nearbyWork;
$('#interact').disabled=!(work||worldInfo.nearby);
$('#interact').textContent=work?'F · '+(work.kind==='sample'?'Inspect sample':work.kind==='monitor'?'Read monitor':'Connect terminal'):worldInfo.nearby?'F · Talk / investigate':'F · Interact';
$('#nearby').textContent=work?work.name:worldInfo.nearby?worldInfo.nearby.name:worldInfo.inVehicle?(touch?'':'Space brakes · S reverses'):worldInfo.vehicleNearby?'Authorized city fleet car':'';
$('#systems').textContent=`${5-state.completed.length} systems down`;
$('#incident-fill').style.width=((5-state.completed.length)/5*100)+'%';
let head,text,eyebrow='DISPATCH';
if(state.tutorial<3){eyebrow='GETTING STARTED';head='First, find your feet.';text=[touch?'Touch the lower-left area and slide to walk. Drag elsewhere to look around.':'Walk with WASD or the arrow keys. Drag the city to look around.',touch?'Walk to the white fleet car and tap Enter fleet car.':'Walk to the white fleet car and press E.',touch?'Hold GAS and steer with your left thumb. BRAKE stops, then reverses.':'Drive a short way: W accelerates, A/D steer, Space brakes.'][state.tutorial]}
else if(state.trackWater&&!waterComplete(state.water)){eyebrow='SIDE JOB · HARBOR WATER WATCH';head='Read the seawall monitors';const left=MONITORS.filter(m=>!state.water?.[m.id]).length;text=`Follow the gold route to the harbor. ${left} monitor record${left===1?'':'s'} left.`}
else if(current()){eyebrow=`INVESTIGATION ${String(MISSIONS.indexOf(current())+1).padStart(2,'0')}`;head=current().title;text=`${state.step===0?'Talk to':'Return to'} ${current().person} at the gold marker, then interact.`}
else if(next()){eyebrow=`INVESTIGATION ${String(MISSIONS.indexOf(next())+1).padStart(2,'0')}`;head=next().title;text=next().objective+' Follow the gold route.'}
else{eyebrow='FREE ROAM';head='The city is back online.';text='All five investigations complete. Explore, find the gold element coins, or try the harbor side job.'}
if(state.active==='power'&&state.step>0){eyebrow='INVESTIGATION 01 · ON SCENE';head='Power to the Block';text=powerStage(state.work)}
$('#objective-eyebrow').textContent=eyebrow;$('#objective-title').textContent=head;$('#objective-text').textContent=text}
const repScore=()=>state.completed.length*100+Math.min(state.revisions,10)*5+MONITORS.filter(m=>state.water?.[m.id]).length*25+(state.discoveries?.length||0)*10;
function interactStation(id){if(state.workChallenge&&id==='identity'&&worldInfo.inVehicle){state.challenge=true;const elapsed=Math.round((Date.now()-state.workChallenge.started)/1000);delete state.workChallenge;record('Fleet route complete','Authorized delivery to Halogen Harbor completed. Separate from chemistry progress.');toast('Fleet delivery complete!'+(state.settings.timer?' Stopwatch: '+elapsed+' seconds.':''));save()}if(id==='hq'){hq();return}const m=MISSIONS.find(m=>m.station===id);if(!m){toast('A future district. Your current investigation is marked in gold.');return}if(state.completed.includes(m.id)){openModal('debrief',`${closeButton()}<div class="eyebrow">CASE CLOSED / ${esc(m.person)}</div><h2>${m.title}</h2><p>${m.debrief}</p><p class="pill teal">${m.reward}</p><div class="actions"><button data-act="close" class="primary">Back to the city</button></div>`);return}if(m.id!==(current()||next())?.id){toast('This investigation unlocks after your current dispatch.');return}if(!state.active){state.active=m.id;state.step=0;state.work={};save()}showMission()}
function intro(m){openModal('mission',`${closeButton()}<div class="eyebrow">INVESTIGATION ${MISSIONS.indexOf(m)+1} / ${esc(m.role)}</div><h2>${m.title}</h2><div class="portrait">${m.initials}</div><div class="speaker">${m.person}</div><p class="quote">“${m.intro}”</p><div class="panel"><div class="eyebrow">YOUR INVESTIGATION</div><p>${m.concept}</p><span class="pill">${m.reward}</span></div><div class="actions"><button class="primary" data-act="accept">Accept investigation</button><button data-act="close">Explore first</button></div>`)}
function showMission(){const m=current();if(!m)return;if(state.step===0){intro(m);return}if(m.id==='power')powerUI();else expandedMission(m.id)}
function legacyPowerUI(){const scans=state.work.scans||[];openModal('mission',`${closeButton()}<div class="eyebrow">MAYA’S WORKBENCH / VIRTUAL MATERIAL TESTS</div><h2>Make the connection.</h2><p>The signal needs a <b>flexible electrical cable</b>. Scan every candidate, then choose a material and test your explanation.</p><div class="cards">${MATERIALS.map(m=>`<div class="card"><span class="symbol">${m.symbol}</span><b>${m.name}</b>${scans.includes(m.id)?`<dl class="scan-data"><dt>Conductivity</dt><dd>${m.conductivity}</dd><dt>Bend test</dt><dd>${m.bend}</dd><dt>Appearance</dt><dd>${m.look}</dd></dl><span class="pill teal">✓ Evidence saved</span>`:`<p>Scanner ready. Identity is labeled; suitability is yours to infer.</p><button data-scan="${m.id}">Scan sample</button>`}</div>`).join('')}</div>${scans.length===3?`<div class="cols"><div><h3>Select a material</h3><div class="tool-row">${MATERIALS.map(m=>`<button data-material="${m.id}" class="${state.work.material===m.id?'selected':''}">${m.name}</button>`).join('')}</div></div><div><h3>Support your prediction</h3><select id="power-reason" aria-label="Evidence for material choice"><option value="">Choose an explanation</option><option value="shiny" ${state.work.reason==='shiny'?'selected':''}>It is shiny, so it must work.</option><option value="both" ${state.work.reason==='both'?'selected':''}>It conducts and bends without breaking.</option><option value="metal" ${state.work.reason==='metal'?'selected':''}>Only metals can conduct electricity.</option></select></div></div><button class="primary" data-act="test-power">Test the flexible circuit</button>`:'<p class="small-note">Observations at approximately 20–25 °C and 1 atm. Tests are simulated; no real materials are handled.</p>'}${footer()}`)}
function complete(){if(state.active==='power')world.setCamera?.('chase');streetPoint=null;streetMessage='';const m=current();if(!m)return;state.completed.push(m.id);state.active=null;state.step=0;state.work={};record(m.title,m.debrief);save();beep('success');banner('INVESTIGATION PASSED',m.title,'+100 REP','passed');modal='celebrate';clearInputs();sync();setTimeout(()=>{if(modal==='celebrate')openModal('complete',`<div class="complete"><div class="badge">${String(state.completed.length).padStart(2,'0')}</div><div class="eyebrow">INVESTIGATION COMPLETE</div><h2>${m.title}</h2><p class="lead">${m.reward}</p><div class="panel"><p>${m.debrief}</p></div><div class="mission-meta" style="justify-content:center"><span class="pill teal">+100 science reputation</span><span class="pill">Revision is good science</span></div><div class="actions" style="justify-content:center"><button class="primary" data-act="close">${next()?'Continue the investigation':'Explore your restored city'}</button><button data-act="summary">View progress</button></div></div>`,'narrow')},state.settings.reducedMotion?200:1800);sync()}
function hint(){const m=current();if(!m)return;const n=state.hints[m.id]||0;state.hints[m.id]=Math.min(n+1,m.hints.length);$('#hint').textContent=`Hint ${Math.min(n+1,m.hints.length)}: ${m.hints[Math.min(n,m.hints.length-1)]}`;save()}
function table(from=null){returnTo=from;const groups={power:[],identity:[2,17,18],family:[1,2,17,18],reaction:[1],ions:[1,2,16,17]};const relevant=groups[state.active]||[];const maxrow=10;let cells=Array.from({length:18},(_,i)=>`<span class="element group-label" style="grid-column:${i+1};grid-row:1">${i+1}</span>`).join('');for(const e of ELEMENTS){let col=e.group,row=e.period+1;if(e.number>=58&&e.number<=71){col=e.number-54;row=10}if(e.number>=90&&e.number<=103){col=e.number-86;row=11}cells+=`<button class="element ${relevant.includes(e.group)?'pattern':''}" data-element="${e.number}" style="grid-column:${col};grid-row:${row};--ec:${colors[e.category]}" aria-label="${e.number}, ${e.name}, ${e.symbol}, ${CATEGORIES[e.category]}"><small>${e.number}</small><strong>${e.symbol}</strong></button>`}openModal('table',`${closeButton()}<div class="eyebrow">FIELD REFERENCE / ALL 118 ELEMENTS</div><h2>The periodic table</h2><div class="tool-row"><input id="element-search" type="search" placeholder="Search name, symbol, or atomic number" aria-label="Search periodic table"><button data-act="table-back">${returnTo?'Return to investigation':'Back to city'}</button></div><p class="small-note">Group numbers run across the top; periods run down the table. ${relevant.length?'Gold outlines highlight families relevant to this investigation.':''}</p><div class="table-scroll"><div class="periodic-grid">${cells}</div></div><div class="legend">${Object.entries(CATEGORIES).map(([k,v])=>`<span style="--ec:${colors[k]}">${v}</span>`).join('')}</div><div class="element-details" id="element-details" aria-live="polite"></div><p class="small-note">${TABLE_NOTE} ${REFERENCE_CONDITIONS}</p>`,'wide');elementDetails(selectedElement)}
function elementDetails(n){selectedElement=n;const e=ELEMENTS.find(x=>x.number===n);$('#element-details').innerHTML=`<div class="big-symbol">${e.symbol}</div><b>${e.name} · atomic number ${e.number}</b><p>${e.number} protons per atom · ${e.group?'Group '+e.group:'Detached series'} · Period ${e.period} · ${CATEGORIES[e.category]}</p><p>Elemental substance: ${esc(e.state)} at reference conditions. ${esc(e.notes||'')}</p>${e.properties?`<p>${Object.entries(e.properties).map(([k,v])=>`<b>${esc(k)}:</b> ${esc(v)}`).join(' · ')}</p>`:''}`}
function notebook(){openModal('notebook',`${closeButton()}<div class="eyebrow">FIELD NOTEBOOK / EVIDENCE & EXPLANATIONS</div><h2>Good science leaves a trail.</h2><div class="tool-row"><button data-act="summary">Progress summary</button><button data-act="practice">Research practice</button><button data-act="table">Open periodic table</button></div><div class="cols"><div><h3>Investigation record</h3>${state.journal.length?state.journal.slice().reverse().map(j=>`<div class="panel"><b>${esc(j.title)}</b><p>${esc(j.text)}</p></div>`).join(''):'<p>Your evidence and explanations will appear here.</p>'}</div><div><h3>The pocket guide</h3><div class="panel"><b>Location is useful evidence</b><p>Atomic number counts protons. Groups are columns; periods are rows. Group 1 alkali metals exclude hydrogen. Group 2 are alkaline earth metals; Group 16 (O, S) commonly −2; Group 17 halogens; Group 18 noble gases.</p><b>Patterns, with exceptions</b><p>Atomic radius generally decreases across a period as effective nuclear attraction increases. Down a group, more occupied energy levels and shielding generally increase radius. First ionization energy generally follows the opposite pattern, with exceptions.</p><div class="shells"><div class="shell-model"><b>+</b></div><span class="mini-label">Simplified shell model<br>Not electron paths or to scale</span></div><p>Down Group 1, the outer electron is farther out and more shielded. It is generally easier to remove, helping explain the Li → Na → K increase in reactivity in comparable virtual tests.</p><b>Atoms, ions, and compounds</b><p>Ions have gained or lost electrons. Common main-group charges: alkali metals +1, Group 2 +2, Group 17 −1. Apply these patterns to appropriate main-group elements, not all transition metals.</p><p>Ionic formulas show the lowest whole-number ratio of ions in a neutral lattice. The properties of a compound differ from those of its constituent elements.</p><b>Oxides and acid/base evidence</b><p>As a general pattern, many nonmetal oxides (such as CO₂ or SO₂) form acidic solutions, and soluble metal oxides (such as CaO or Na₂O) form basic solutions. Exceptions exist: insoluble oxides such as Al₂O₃ leave water near neutral.</p><b>Interpreting water-monitor records</b><p>At 25 °C, an aqueous pH below 7 is acidic, 7 is neutral, and above 7 is basic. This observation alone cannot identify an element or prove its metal/nonmetal category. Evidence about composition is also needed.</p><b>Families are patterns</b><p>Noble gases have low reactivity under many ordinary conditions; some form compounds. Not all metals are magnetic. Graphite, a form of the nonmetal carbon, conducts electricity. Metalloids summarize a range of intermediate behavior.</p><a href="teacher.html" target="_blank" rel="noopener">Teacher guide & scientific sources</a></div></div></div>`,'wide')}
function summary(){openModal('summary',`${closeButton()}<div class="eyebrow">YOUR PROGRESS / LOCAL TO THIS BROWSER</div><h2>${state.completed.length}/5 investigations closed</h2><div class="cols"><div class="panel"><h3>Chemistry</h3>${MISSIONS.map(m=>`<div class="progress-row"><span>${state.completed.includes(m.id)?'✓':'○'} ${m.title}<br><small>${m.concept}</small></span></div>`).join('')}<p>${state.revisions} prediction revisions. Hints are available without a mastery penalty.</p></div><div class="panel"><h3>Exploration & driving</h3><p>${state.practice?.length||0}/3 optional research activities<br>${state.discoveries.length} city discoveries<br>${Math.round(state.walked/10)} exploration units on foot<br>${Math.round(state.driven/10)} fleet driving units<br>Optional delivery: ${state.challenge?'completed':'not completed'}</p><p class="small-note">These achievements do not affect access to chemistry learning. No names, accounts, or public leaderboards.</p><button data-act="download">Download progress summary</button></div></div><div class="actions"><button class="primary" data-act="close">Back to city</button></div>`)}
function download(){const text=`ELEMENT CITY: PERIODIC PURSUIT\nStudent progress (no identifying information)\n\n${MISSIONS.map(m=>`${state.completed.includes(m.id)?'[Complete]':'[Not complete]'} ${m.title}\n${m.concept}`).join('\n\n')}\n\nOptional research: ${state.practice?.length||0}/3\n${PRACTICE.filter(p=>state.practice?.includes(p.id)).map(p=>p.title+': '+p.concept).join('\n')}\n\nPrediction revisions: ${state.revisions}\nDiscoveries: ${state.discoveries.length}\nOptional fleet route: ${state.challenge?'complete':'not complete'}\n\nCompletion records participation, not an independent assessment of mastery.`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='element-city-progress.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function cityMap(){openModal('map',`${closeButton()}<div class="eyebrow">ELEMENT CITY / MAP</div><h2>Know your neighborhood.</h2><canvas class="map-large" id="large-map" width="1200" height="900"></canvas><div class="map-legend">${stations.map(s=>`<div>${state.completed.includes(s.id)?'✓':'◆'} ${s.code} · ${s.name} ${state.completed.includes(s.id)?'· restored':s.id===trackedTarget()?'· <b style="color:var(--gold)">current destination</b>':''}</div>`).join('')}${waterUnlocked()?`<div>💧 Harbor Water Watch · ${MONITORS.filter(m=>state.water?.[m.id]).length}/3 monitors</div>`:''}</div><p class="small-note">Gold line = suggested street route. White arrow = you. Streets beyond the barriers are outside the response district.</p>`,'wide');
const cv=$('#large-map'),c=cv.getContext('2d');if(world.drawFullMap)world.drawFullMap(c,cv.width,cv.height);else{c.imageSmoothingEnabled=false;c.drawImage($('#minimap'),0,0,cv.width,cv.height)}}
function guide(){openModal('guide',`${closeButton()}<div class="eyebrow">HOW TO PLAY</div><h2>Explore. Predict. Test. Revise.</h2><div class="help-grid"><div><b>iPad · Move & steer</b><p>Touch anywhere in the lower-left area and slide. The stick appears under your thumb. In the car it steers.</p></div><div><b>iPad · Drive</b><p>Hold GAS (right). BRAKE stops the car; keep holding to reverse. You can steer and press GAS at the same time.</p></div><div><b>iPad · Look</b><p>Drag the city with your other thumb: sideways turns the camera, up/down tilts it. Recenter snaps it behind you.</p></div><div><b>Keyboard</b><p>WASD / arrows move or drive · Shift jogs · Space brakes · E enter/exit car · F interact · T table · N notebook · M map · C camera · R recenter · Esc pause.</p></div><div><b>Follow the gold</b><p>The gold route on the street and radar leads to your current destination. Tall light beams mark contacts.</p></div><div><b>Take your time</b><p>Reading pauses the world. Missions are untimed. Hints get more specific and wrong predictions can always be revised.</p></div></div><p>Pause has graphics quality, the guide line, control size, camera sensitivity, reduced motion, mission restart and Return to HQ.</p><p class="small-note">A fictional teaching city. Tests are virtual and are not instructions for real experiments. No weapons, no injuries; fleet cars are authorized. The 3D city is not fully screen-reader accessible; mission panels are.</p><div class="actions"><button class="primary" data-act="close-guide">${state.started?'Back to city':'Back to title'}</button><a href="teacher.html" target="_blank" rel="noopener">Teacher overview & sources</a></div>`)}
function pause(){const q=state.settings.quality||'auto';openModal('pause',`${closeButton()}<div class="eyebrow">PAUSED</div><h2>The city can wait.</h2><div class="options"><label>Graphics quality <select id="quality"><option value="auto" ${q==='auto'?'selected':''}>Automatic (recommended)</option><option value="high" ${q==='high'?'selected':''}>High · sharpest shadows</option><option value="balanced" ${q==='balanced'?'selected':''}>Balanced</option><option value="low" ${q==='low'?'selected':''}>Battery saver · no shadows</option></select></label><label><input id="guide-line" type="checkbox" ${state.settings.guideLine!==false?'checked':''}>Show the gold route on the street</label><label>Sound volume <input id="volume" type="range" min="0" max="1" step=".1" value="${state.settings.volume}"><span id="vol-label">${Math.round(state.settings.volume*100)}%</span></label><label><input id="reduced" type="checkbox" ${state.settings.reducedMotion?'checked':''}>Reduce camera motion and effects</label><label><input id="show-touch" type="checkbox" ${touchUI()?'checked':''}>Show on-screen touch controls</label><label>Touch movement <select id="control-style"><option value="stick" ${state.settings.controlStyle!=='buttons'?'selected':''}>Floating thumbstick</option><option value="buttons" ${state.settings.controlStyle==='buttons'?'selected':''}>Arrow buttons</option></select></label><label>Control size <input id="control-size" type="range" min="0.8" max="1.3" step=".1" value="${state.settings.controlSize||1}"></label><label>Camera sensitivity <input id="camera-sensitivity" type="range" min="0.5" max="1.5" step=".25" value="${state.settings.cameraSensitivity||1}"></label><label><input id="auto-camera" type="checkbox" ${state.settings.autoCamera!==false?'checked':''}>Ease the camera back behind me</label><label><input id="timer" type="checkbox" ${state.settings.timer?'checked':''}>Optional delivery stopwatch (never a deadline)</label></div><p class="small-note">Chemistry missions are untimed.${world.canvas?.dataset?.renderFps?` Graphics: ${world.canvas.dataset.quality||''} · ~${world.canvas.dataset.renderFps} fps.`:''}</p><div class="actions"><button class="primary" data-act="close">Resume</button><button data-act="recenter">Recenter camera</button><button data-act="recover">Return to HQ</button><button data-act="restart">Restart active mission</button><button data-act="guide">Controls guide</button><button data-act="summary">Progress</button><button class="danger" data-act="reset-confirm">Reset all progress</button></div><p class="small-note">${save()?'Progress saved in this browser.':'Browser storage is unavailable. You can play, but progress will not survive reloading.'}</p>`,'narrow')}
function hq(){openModal('hq',`${closeButton()}<div class="eyebrow">PERIODIC RESEARCH CENTER</div><h2>Welcome back, investigator.</h2><p>“The equipment is fictional. The reasoning is yours.” — Dr. Imani Park</p><div class="actions"><button class="primary" data-act="dispatch">Review current dispatch</button><button data-act="water">${waterComplete(state.water)?'Harbor Water Watch ✓':'Side job: Harbor Water Watch'}</button><button data-act="notebook">Field notebook</button><button data-act="practice">Research practice</button><button data-act="challenge">Optional fleet delivery</button><button data-act="close">Explore</button></div><p class="small-note">Side jobs and the fleet delivery are optional. They never block the five investigations.</p>`)}
function waterIntro(){openModal('water',`${closeButton()}<div class="eyebrow">SIDE JOB / HARBOR WATER WATCH</div><h2>What do the indicators say?</h2><div class="portrait">NQ</div><div class="speaker">Noor Quill · Harbor logistics</div><p class="quote">“Three seawall monitors logged sealed water records, each with a known oxide added. I need someone who can read an indicator and say whether the result fits the usual pattern.”</p><div class="panel"><b>Your job</b><p>Drive to the harbor end of each street. At each monitor, classify the record as acidic, neutral, or basic, decide whether the oxide’s other element is a metal or nonmetal, and judge whether the result fits the general pattern.</p></div><p class="small-note">Records are fictional and sealed. Nothing here describes a real procedure.</p><div class="actions"><button class="primary" data-act="water-go">${state.trackWater?'Keep following the route':'Set the route'}</button><button data-act="close">Not now</button></div>`)}
function monitorUI(id){const m=MONITORS.find(x=>x.id===id);if(!m)return;const a=state.waterDraft?.[id]||{},done=state.water?.[id];
openModal('monitor',`${closeButton()}<div class="eyebrow">HARBOR WATER WATCH / ${esc(m.name.toUpperCase())}</div><h2>${m.oxide} <span style="color:var(--muted);font-weight:600">(${m.formula})</span></h2><p>${m.record}</p><div class="vial" style="--vial:${m.color}"><i></i><div><b>${m.colorName}</b><br><small>Universal indicator in the sealed record</small></div></div><div class="indicator-scale" aria-label="Indicator colour scale">${INDICATOR_SCALE.map(x=>`<div style="background:${x.color}">${x.label}<br>${x.range}</div>`).join('')}</div><p class="small-note">Indicator colours vary by brand; this game uses one common scale at about 25 °C.</p>
<div class="options"><label>The water sample is <select id="mon-ph"><option value="">choose</option>${['acidic','neutral','basic'].map(v=>`<option ${a.ph===v?'selected':''}>${v}</option>`).join('')}</select></label><label>${m.elementName[0].toUpperCase()+m.elementName.slice(1)} (${m.element}) is a <select id="mon-element"><option value="">choose</option>${['metal','nonmetal'].map(v=>`<option ${a.element===v?'selected':''}>${v}</option>`).join('')}</select></label><label>This record <select id="mon-fits"><option value="">choose</option><option value="yes" ${a.fits==='yes'?'selected':''}>fits the general oxide pattern</option><option value="exception" ${a.fits==='exception'?'selected':''}>is an exception to the pattern</option></select></label></div>
<div class="actions"><button class="primary" data-act="check-monitor" data-monitor="${id}">${done?'Check again':'Log my reading'}</button><button data-act="monitor-hint" data-monitor="${id}">Hint</button><button data-act="table-from-monitor" data-monitor="${id}">Periodic table</button><button data-act="close">Back to the harbor</button></div><div id="hint" class="hint" role="status"></div><div id="feedback" class="feedback" role="status">${done?esc(m.explain):''}</div>`)}
function dispatch(){const m=current()||next();
openModal('dispatch',`${closeButton()}<div class="eyebrow">MISSION PHONE / DISPATCH</div><h2>${m?m.title:'All systems online'}</h2>${m?`<div class="speaker">${m.person} · ${m.role}</div><p>“${m.intro}”</p><div class="panel"><b>Destination</b><p>${m.objective} The gold route on the street and radar leads there.</p><b>Investigate</b><p>${m.concept}</p></div>`:'<p>Five investigations closed. Your explanations helped restore Element City. Explore, collect the gold element coins, and export your progress from the notebook.</p>'}${waterUnlocked()&&!waterComplete(state.water)?`<p class="small-note">Optional side job available: Harbor Water Watch (${MONITORS.filter(x=>state.water?.[x.id]).length}/3).</p>`:''}<div class="actions"><button class="primary" data-act="close">Return to city</button><button data-act="map">View city map</button><button data-act="shuttle">Take city shuttle</button>${waterUnlocked()&&!waterComplete(state.water)?'<button data-act="water">Harbor side job</button>':''}</div>`)}
function powerUI(){if(!world.focusWorkshop){legacyPowerUI();return}closeModal();streetMessage='Maya: inspect each sample station. Everything here is a virtual model.';world.focusWorkshop();streetPoint=null;streetStamp='';sync();world.notify();}
function enterStreetPoint(id){if(String(id).startsWith('monitor-')){if(world.player.inVehicle){toast('Park and step out to read the monitor.');return}monitorUI(id.slice(8));return}const point=POWER_POINTS.find(p=>p.id===id);if(!point||state.active!=='power'||state.step<1)return;if(world.player.inVehicle){toast('Park and exit to use the sample stations.');return}if(Math.hypot(world.player.x-point.x,world.player.y-point.y)>155){toast('Walk closer to this station.');return}streetPoint=point;streetMessage='';streetStamp='';renderStreet();}
const sampleResults={conductivity:m=>`Conductivity: ${m.conductivity.toLowerCase()}.`,bend:m=>`Flex test: ${m.bend.toLowerCase()}.`,malleability:m=>m.id==='copper'?'Compression model: flattens into a sheet without shattering. This is malleability.':'Compression model: fractures rather than forming a sheet. This sample is brittle.'};
function renderStreet(){const el=$('#field-workshop');if(!el)return;const enabled=state.started&&!modal&&state.active==='power'&&state.step>0&&!!world.focusWorkshop;el.classList.toggle('hidden',!enabled);document.body.classList.toggle('street-investigation',enabled);if(!enabled)return;
 if(streetPoint&&Math.hypot(world.player.x-streetPoint.x,world.player.y-streetPoint.y)>165){streetPoint=null;streetMessage=''}
 const stamp=JSON.stringify([streetPoint?.id,state.work,streetMessage]);if(stamp===streetStamp)return;streetStamp=stamp;const point=streetPoint;
 let content=`<h3>Restore the street signals</h3><p>${powerStage(state.work)}</p><p class="small-note">Walk to a labeled station. Tap it in the city or press Interact nearby. Tests are fully virtual at about 20–25 °C, 1 atm.</p>`;
 if(point?.kind==='sample'){const m=MATERIALS.find(x=>x.id===point.material),done=state.work.measurements?.[m.id]||[];content=`<h3>${m.name} station</h3><p>Run each virtual test, then compare the sample records.</p><div class="street-actions">${POWER_TESTS.map(t=>`<button data-street-test="${t}">${done.includes(t)?'✓ ':''}${{conductivity:'Test current',bend:'Flex sample',malleability:'Compress sample'}[t]}</button>`).join('')}</div><div class="street-evidence">${done.map(t=>`<p>${sampleResults[t](m)}</p>`).join('')}<p>Appearance: ${m.look}.</p></div><button data-street="carry" ${!powerReady(state.work)?'disabled':''}>Carry this sample</button>${!powerReady(state.work)?'<p class="small-note">Inspect all three samples before choosing.</p>':''}`;}
 if(point?.kind==='socket'){const end=point.id.at(-1),connected=state.work.connections?.includes(end);content=`<h3>${point.name}</h3><p>Carrying: <b>${state.work.material?MATERIALS.find(x=>x.id===state.work.material)?.name:'no sample selected'}</b></p><button data-street="connect">${connected?'Reconnect':'Connect'} terminal ${end.toUpperCase()}</button>${state.work.connections?.includes('b')?`<p>Choose the evidence your flexible cable must satisfy:</p><div class="street-actions">${[['conducts','Carries current'],['bends','Bends without breaking'],['shiny','Looks shiny']].map(([key,name])=>`<button data-street-evidence="${key}" aria-pressed="${!!state.work.support?.includes(key)}" class="${state.work.support?.includes(key)?'selected':''}">${name}</button>`).join('')}</div><button class="primary" data-street="run">Run virtual flex cycle</button>`:''}${state.work.success?'<button class="primary" data-street="finish">Return signals to service</button>':''}`;}
 el.innerHTML=`<div class="eyebrow">STREET INVESTIGATION / MAYA’S VIRTUAL WORKSHOP</div>${content}<p class="street-feedback" role="status">${esc(streetMessage)}</p><div class="street-tools"><button data-street="overview">Focus workshop</button><button data-street="roam">Follow camera</button><button data-street="hint">Hint</button><button data-street="table">Table</button><button data-street="records">Evidence</button><button data-street="notebook">Notebook</button></div>`;
}
function streetRecords(){const lines=MATERIALS.map(m=>`<div class="panel"><h3>${m.name}</h3>${POWER_TESTS.filter(t=>state.work.measurements?.[m.id]?.includes(t)).map(t=>`<p>${sampleResults[t](m)}</p>`).join('')||'<p>No observations recorded yet.</p>'}</div>`).join('');openModal('street-records',`${closeButton()}<div class="eyebrow">MEASURED EVIDENCE / VIRTUAL TESTS</div><h2>Compare your sample records</h2><div class="cards">${lines}</div><p class="small-note">Conductivity alone is not exclusive to metals. Categories summarize patterns; use several properties for a material decision.</p><button class="primary" data-act="close">Back to the street</button>`);}
function streetChange(){streetStamp='';sync();save();renderStreet();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.street,test=b.dataset.streetTest,evidence=b.dataset.streetEvidence;if(!action&&!test&&!evidence)return;
 if(action==='overview'){world.focusWorkshop();return}if(action==='roam'){world.setCamera('chase');return}if(action==='table'){table('mission');return}if(action==='records'){streetRecords();return}if(action==='notebook'){notebook();return}
 if(action==='hint'){const n=state.hints.power||0;const hints=['Use the sample labels in the upper part of the workshop. Walk with the stick, then tap a station or Interact.','Run current, flex and compression tests on all three samples. Compare several properties.','Choose a conductor that bends; connect A, then B. Support your choice with current flow and flexibility.'];state.hints.power=Math.min(n+1,3);streetMessage=hints[Math.min(n,2)];streetChange();return}
 const point=streetPoint;if(!point||world.player.inVehicle||Math.hypot(world.player.x-point.x,world.player.y-point.y)>165){toast('Walk to a station and interact first.');return}
 if(test&&point.kind==='sample'){const m=MATERIALS.find(x=>x.id===point.material);measureSample(state.work,m.id,test);state.work.lastTest={material:m.id,test};streetMessage=sampleResults[test](m);record('Virtual observation · '+m.name,streetMessage);beep();}
 if(action==='carry'&&point.kind==='sample'&&powerReady(state.work)){state.work.material=point.material;state.work.connections=[];state.work.success=false;state.work.failed=false;streetMessage='Sample selected. Walk to cabinet terminal A, then signal terminal B.';}
 if(action==='connect'&&point.kind==='socket'){const r=connectTerminal(state.work,point.id.at(-1));streetMessage=r.text;beep(r.ok?'tap':'wrong');}
 if(evidence){state.work.support||=[];state.work.support=state.work.support.includes(evidence)?state.work.support.filter(x=>x!==evidence):[...state.work.support,evidence];state.work.success=false;}
 if(action==='run'&&state.work.connections?.includes('b')){const support=state.work.support||[];const reason=support.length===2&&support.includes('conducts')&&support.includes('bends')?'both':'shiny';const r=validatePower(state.work.material,reason);state.work.success=r.ok;state.work.failed=!r.ok;streetMessage=r.text;if(!r.ok){state.revisions++;record('Street prediction revised',r.text);if(state.work.material!=='copper')state.work.connections=[];}beep(r.ok?'success':'wrong');}
 if(action==='finish'&&state.work.success){complete();return}streetChange();
});
let engineSound=null;
function updateEngineSound(){const live=state.started&&!modal&&worldInfo.inVehicle&&state.settings.volume>0;if(!live){if(engineSound&&audioCtx)engineSound.gain.gain.setTargetAtTime(0,audioCtx.currentTime,.12);return}try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();if(!engineSound){const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain(),filter=audioCtx.createBiquadFilter();oscillator.type='triangle';filter.type='lowpass';filter.frequency.value=240;gain.gain.value=0;oscillator.connect(filter);filter.connect(gain);gain.connect(audioCtx.destination);oscillator.start();engineSound={oscillator,gain};}engineSound.oscillator.frequency.setTargetAtTime(42+Math.abs(worldInfo.speed||0)*.3,audioCtx.currentTime,.14);engineSound.gain.gain.setTargetAtTime(state.settings.volume*.045,audioCtx.currentTime,.1);}catch{}}
function practiceMenu(){openModal('practice',`${closeButton()}<div class="eyebrow">RESEARCH PRACTICE / OPTIONAL</div><h2>Calibrate your reasoning</h2><p>New situations for applying periodic patterns. These activities are separate from the five city investigations.</p><div class="choice-list">${PRACTICE.map(p=>`<button data-practice-open="${p.id}">${state.practice?.includes(p.id)?'✓ ':''}${p.title}<br><small>${p.concept}</small></button>`).join('')}</div><p class="small-note">Use the table and notebook whenever you need them. Practice records are local to this browser.</p>`);}
function practiceUI(id){practiceId=id;const task=PRACTICE.find(x=>x.id===id);let controls='';if(id==='radius')controls=`<div class="options"><label>Atomic radius<select id="practice-radius"><option value="">Predict a change</option><option value="increase">Increases</option><option value="decrease">Decreases</option></select></label><label>First ionization energy<select id="practice-energy"><option value="">Predict a change</option><option value="increase">Increases</option><option value="decrease">Decreases</option></select></label><label>Explain<select id="practice-reason"><option value="">Choose a cause</option><option value="protons">Added protons alone explain the outer electron’s behavior.</option><option value="levels">Added occupied energy levels and shielding affect outer-electron attraction.</option></select></label></div>`;
 if(id==='indicator')controls=`<div class="options"><label>Aqueous record<select id="practice-type"><option value="">Classify the pH</option><option value="basic">Basic</option><option value="neutral">Neutral</option><option value="acidic">Acidic</option></select></label><label>Source identity<select id="practice-identity"><option value="">Assess the evidence</option><option value="metal">The pH alone proves the source is a metal.</option><option value="nonmetal">The pH alone proves the source is a nonmetal.</option><option value="insufficient">More evidence is needed to identify the source.</option></select></label></div>`;
 if(id==='ratio')controls=`<div class="options"><label>Li⁺ count<select id="practice-positive">${[0,1,2,3,4].map(n=>`<option>${n}</option>`).join('')}</select></label><label>S²⁻ count<select id="practice-negative">${[0,1,2,3,4].map(n=>`<option>${n}</option>`).join('')}</select></label></div>`;
 openModal('practice-task',`${closeButton()}<div class="eyebrow">OPTIONAL VIRTUAL RESEARCH</div><h2>${task.title}</h2><p>${task.prompt}</p>${controls}<div class="actions"><button class="primary" data-practice-check="${id}">Test prediction</button><button data-practice-hint="${id}">Hint</button><button data-practice-table="${id}">Periodic table</button><button data-act="practice">Other practice</button></div><div id="feedback" class="feedback" role="status"></div><div id="hint" class="hint" role="status"></div>`);for(const [key,value] of Object.entries(state.practiceDrafts?.[id]||{})){const input=$('#practice-'+key);if(input)input.value=value;}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.practiceTable){table('practice');return}if(b.dataset.practiceOpen)practiceUI(b.dataset.practiceOpen);if(b.dataset.practiceHint){const task=PRACTICE.find(t=>t.id===b.dataset.practiceHint);const n=Number(b.dataset.hintLevel||0);$('#hint').textContent=task.hints[Math.min(n,1)];b.dataset.hintLevel=String(n+1)}if(b.dataset.practiceCheck){const id=b.dataset.practiceCheck,answer={};for(const key of ['radius','energy','reason','type','identity','positive','negative']){const el=$('#practice-'+key);if(el)answer[key]=['positive','negative'].includes(key)?Number(el.value):el.value;}const ok=checkPractice(id,answer),task=PRACTICE.find(t=>t.id===id);feedback(ok?task.explanation:'The model needs revision. Compare your prediction with the evidence and use a hint if needed.',!ok);if(ok){state.practice||=[];if(!state.practice.includes(id))state.practice.push(id);record(task.title,task.explanation);save();}}});
function expandedMission(id){({identity:identityUI,family:familyUI,reaction:reactionUI,ions:ionsUI})[id]?.()}
function identityUI(){const scanned=state.work.scanned||[];const choices=['Mg','Ca','Ar','Ne','Br','Cl','Cu','Si'];openModal('mission',`${closeButton()}<div class="eyebrow">HALOGEN HARBOR / SEALED SAMPLE RECORDS</div><h2>Give the cargo its identity.</h2><p>Retrieve the records, compare evidence, and consult the table. The scanner gives observations; <b>you infer the identity</b>.</p><div class="cards">${SAMPLES.map(s=>`<div class="card"><span class="symbol">${s.id}</span><b>${s.name}</b><p>Shipping record: ${s.clues.join(' · ')}</p>${scanned.includes(s.id)?`<ul class="evidence-list">${s.observations.map(o=>`<li>${o}</li>`).join('')}</ul><label class="mini-label">Inferred identity<select data-identify="${s.id}" aria-label="Identify ${s.name}"><option value="">Select element</option>${choices.map(c=>`<option value="${c}" ${state.work.answers?.[s.id]===c?'selected':''}>${c} · ${ELEMENTS.find(e=>e.symbol===c).name}</option>`).join('')}</select></label>`:`<button data-crate="${s.id}">Scan sealed record</button>`}</div>`).join('')}</div><p class="small-note">Virtual records only. No reactive or hazardous materials are handled.</p><button class="primary" data-act="test-identities" ${scanned.length<3?'disabled':''}>Test shipment labels</button>${footer()}`)}
const familyNames={alkali:'Alkali metals · Group 1',alkaline:'Alkaline earths · Group 2',halogen:'Halogens · Group 17',noble:'Noble gases · Group 18',separate:'Hydrogen · Separate nonmetal'};
function familyUI(){const assigned=state.work.assignments||{},selected=state.work.sample;openModal('mission',`${closeButton()}<div class="eyebrow">FAMILY ARCHIVE / REBUILD THE SHELVES</div><h2>Find where each sample belongs.</h2><p>Tap an element tile, then tap its family shelf. Hydrogen needs a deliberate decision. You can move a tile again before testing.</p><div class="sample-tray">${FAMILY_SAMPLES.map(s=>`<button data-family-sample="${s.symbol}" class="sample-tile ${selected===s.symbol?'selected':''}" aria-label="Sort ${s.symbol}${assigned[s.symbol]?', currently '+familyNames[assigned[s.symbol]]:''}"><b>${s.symbol}</b><span>${assigned[s.symbol]?'✓ Assigned':'Unsorted'}</span></button>`).join('')}</div><p id="sort-instruction">${selected?`Selected: ${selected}. Choose a shelf.`:'Choose an element tile to begin.'}</p><div class="family-shelves">${Object.entries(familyNames).map(([k,v])=>`<button data-shelf="${k}" class="shelf"><b>${v}</b><span>${FAMILY_SAMPLES.filter(x=>assigned[x.symbol]===k).map(x=>x.symbol).join(' · ')||'Empty shelf'}</span></button>`).join('')}</div><div class="actions"><button class="primary" data-act="test-families">Test the family sorter</button></div>${footer()}`)}
function reactionUI(){const order=state.work.order||[],observed=state.work.observed;openModal('mission',`${closeButton()}<div class="eyebrow">ALKALI AVENUE / FULLY VIRTUAL LABORATORY</div><h2>Repair a prediction.</h2><p>Predict the order from <b>lower to higher reactivity</b> under comparable simulated conditions. Tap each element in order, then run the virtual records.</p><div class="cols"><div class="panel"><h3>Your predicted order</h3><div class="ranking">${[0,1,2].map(i=>`<div><small>${['LOWER','MIDDLE','HIGHER'][i]}</small><strong>${order[i]||'?'}</strong></div>`).join('')}</div><div class="tool-row">${['K','Li','Na'].map(x=>`<button data-rank="${x}" ${order.includes(x)?'disabled':''}>${x}</button>`).join('')}<button data-act="clear-rank">Reorder</button></div><button class="primary" data-act="run-reaction" ${order.length<3?'disabled':''}>Run virtual observations</button><p class="small-note">Qualitative model, not measured rates. The game provides no real reaction procedure.</p></div><div class="panel"><h3>Observation record</h3>${observed?['Li','Na','K'].map((e,i)=>`<div class="virtual-readout"><b>${e}</b><span>${['Lower response','Intermediate response','Higher response'][i]}</span><div class="motion-line"><span style="width:${[24,55,90][i]}%"></span></div></div>`).join('')+'<p class="small-note">Comparable conditions. All three have one outer-shell electron in a simplified model.</p>':'<p>First make a prediction. Observations appear when you run the virtual test.</p><div class="shells"><div class="shell-model"><b>+</b></div><span class="mini-label">Simplified shell model<br>Not to scale; not an electron path</span></div>'}</div></div>${observed?`<h3>What explains the observed pattern?</h3><div class="choice-list">${[['protons','More protons alone make the outer electron easier to remove.'],['shielding','More occupied levels and shielding place the outer electron farther out, making it easier to remove.'],['electrons','These atoms gain more outer-shell electrons down the group.']].map(([k,t])=>`<button data-explain="${k}" class="${state.work.explanation===k?'selected':''}">${t}</button>`).join('')}</div><div class="actions"><button class="primary" data-act="test-reaction">Test the revised model</button></div>`:''}${footer()}`)}
const chargeLabel=n=>`${Math.abs(n)>1?Math.abs(n):''}${n>0?'+':'−'}`;
function ionsUI(){const index=state.work.ionIndex||0;if(index>=ION_TASKS.length){compoundUI();return}const task=ION_TASKS[index],c=state.work.cations||0,a=state.work.anions||0;const result=neutralFormula(task.cation,task.anion,c,a);openModal('mission',`${closeButton()}<div class="eyebrow">ION RELAY / FICTIONAL CITY DEVICE / CHANNEL ${index+1} OF 3</div><h2>Balance the charge.</h2><p>Build the <b>smallest neutral ratio</b> for ${task.name.toLowerCase()}. Add or remove ions. The total charge must be zero, with both ion types present.</p><div class="cols"><div class="panel"><h3>Positive ions</h3><div class="ion-control"><button data-ion="cations" data-delta="-1" aria-label="Remove positive ion">−</button><strong>${c}</strong><button data-ion="cations" data-delta="1" aria-label="Add positive ion">+</button></div><div class="ion-particles">${Array.from({length:c},()=>`<span class="ion-dot">${task.cation.symbol}<sup>${chargeLabel(task.cation.charge)}</sup></span>`).join('')}</div><p class="small-note">Each ${task.cation.symbol} ion has charge +${task.cation.charge}.</p></div><div class="panel"><h3>Negative ions</h3><div class="ion-control"><button data-ion="anions" data-delta="-1" aria-label="Remove negative ion">−</button><strong>${a}</strong><button data-ion="anions" data-delta="1" aria-label="Add negative ion">+</button></div><div class="ion-particles">${Array.from({length:a},()=>`<span class="ion-dot negative">${task.anion.symbol}<sup>${chargeLabel(task.anion.charge)}</sup></span>`).join('')}</div><p class="small-note">Each ${task.anion.symbol} ion has charge ${task.anion.charge}.</p></div></div><div class="formula">${c&&a?result.formula.replace(/(\d+)/g,'<sub>$1</sub>'):'Add both ion types'}</div><div class="charge">${c}(+${task.cation.charge}) + ${a}(${task.anion.charge}) = <b>${result.net>0?'+':''}${result.net}</b></div><p class="small-note">Simplified ion-count model. Formula units describe ion ratios in an extended lattice, not separate molecules.</p><div class="actions"><button class="primary" data-act="test-ions">Test relay channel</button></div>${footer()}`)}
function compoundUI(){openModal('mission',`${closeButton()}<div class="eyebrow">ION RELAY / FINAL MATERIAL CHECK</div><h2>A compound has its own identity.</h2><div class="cards"><div class="card"><span class="symbol">Na</span><b>Sodium metal</b><p>A reactive metallic elemental substance.</p></div><div class="card"><span class="symbol">Cl₂</span><b>Chlorine</b><p>A gaseous elemental substance at room conditions.</p></div><div class="card"><span class="symbol">NaCl</span><b>Sodium chloride</b><p>An ionic solid made of Na⁺ and Cl⁻ in a lattice.</p></div></div><h3>What should the city’s material record say?</h3><div class="choice-list"><button data-compound="inherited">NaCl automatically has the properties of sodium metal and chlorine gas.</button><button data-compound="different">NaCl is a compound with properties different from those elemental substances.</button><button data-compound="mixture">NaCl is a physical mixture of unchanged sodium metal and chlorine gas.</button></div>${footer()}`)}

const actions={start,close:closeModal,guide,pause,table:()=>table(),notebook,summary,map:cityMap,download,dispatch,'close-guide':()=>state.started?closeModal():title(),'skip-tutorial':()=>{state.tutorial=3;closeModal();toast('Walking route enabled. Follow the gold marker to Maya.');save()},accept:()=>{state.step=1;{const m=current();if(m)setTimeout(()=>banner(`INVESTIGATION ${String(MISSIONS.indexOf(m)+1).padStart(2,'0')}`,m.title,m.concept),60)}showMission();save()},'mission-table':()=>table('mission'),'table-back':()=>returnTo==='mission'?showMission():returnTo==='practice'?practiceUI(practiceId):typeof returnTo==='string'&&returnTo.startsWith('monitor:')?monitorUI(returnTo.slice(8)):closeModal(),hint,'test-power':()=>{state.work.reason=$('#power-reason').value;const r=validatePower(state.work.material,state.work.reason);if(r.ok){feedback(r.text);$('#feedback').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-act="finish">Restore the signals</button></div>')}else feedback(r.text,true)},finish:complete,recover:()=>{world.recover();closeModal();toast('Returned safely to the research plaza.');save()},restart:()=>{if(state.active){state.work={};state.step=0;save();closeModal();toast('Active investigation restarted. Meet your contact to begin again.')}else toast('No active investigation to restart.')},'reset-confirm':()=>openModal('reset',`${closeButton()}<h2>Start a new investigation?</h2><p>This clears mission progress, evidence, discoveries, and settings on this browser.</p><div class="actions"><button class="danger" data-act="reset">Reset all progress</button><button data-act="pause">Keep my progress</button></div>`,'narrow'),reset:()=>{state=freshState();world.loadPosition({x:520,y:1050,walked:0,driven:0,discovered:[]});world.recover();writeSave(storage,state);title()},challenge:()=>{state.workChallenge={started:Date.now()};closeModal();toast('Fleet route started: drive to Halogen Harbor and interact. No deadline.');save()}};

Object.assign(actions,{recenter:()=>{world.recenterCamera?.();toast('Camera centered behind you.');if(modal==='pause')closeModal()},practice:practiceMenu,shuttle:()=>{const target=stations.find(s=>s.id===(state.active||next()?.id));if(target){world.loadPosition({...world.getState(),x:target.x,y:target.y+75,inVehicle:false,speed:0});world.notify();closeModal();world.interact()}},reload:()=>location.reload(),camera:()=>{const mode=world.setCamera?.(world.viewMode==='overhead'?'chase':'overhead');toast(mode==='overhead'?'Overhead camera':'Third-person camera')},
 'test-identities':()=>{const r=validateIdentities(state.work.answers);feedback(r.text,!r.ok);if(r.ok)$('#feedback').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-act="finish">Restore harbor deliveries</button></div>')},
 'test-families':()=>{const r=validateFamilies(state.work.assignments);feedback(r.text,!r.ok);if(r.ok)$('#feedback').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-act="finish">Reopen the archive</button></div>')},
 'clear-rank':()=>{state.work.order=[];reactionUI();save()},
 'run-reaction':()=>{state.work.observed=true;record('Virtual reactivity observations','Comparable qualitative records: lithium lower, sodium intermediate, potassium higher response. Prediction: '+state.work.order.join(' < '));reactionUI();save()},
 'test-reaction':()=>{const r=validateReaction(state.work.order,state.work.explanation);feedback(r.text,!r.ok);if(r.ok)$('#feedback').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-act="finish">Repair the response model</button></div>')},
 'test-ions':()=>{const t=ION_TASKS[state.work.ionIndex||0],r=neutralFormula(t.cation,t.anion,state.work.cations||0,state.work.anions||0);if(!r.neutral)feedback('The channel needs both ion types and zero total charge. Add the displayed positive and negative charges, then adjust the counts.',true);else if(!r.simplest)feedback('The charges balance. Now reduce to the smallest whole-number ratio: formula units use the simplest ion ratio.',true);else{feedback('Channel stable. '+t.properties);$('#feedback').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-act="next-ion">Save this channel</button></div>')}},
 'next-ion':()=>{const t=ION_TASKS[state.work.ionIndex||0];record('Balanced ionic model · '+t.formula,t.properties);state.work.ionIndex=(state.work.ionIndex||0)+1;state.work.cations=0;state.work.anions=0;ionsUI();save()}
});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.crate){state.work.scanned=[...(state.work.scanned||[]),b.dataset.crate];const s=SAMPLES.find(x=>x.id===b.dataset.crate);record('Measured evidence · '+s.name,s.clues.join(', ')+'. '+s.observations.join('; ')+'.');identityUI();save()}
 if(b.dataset.familySample){state.work.sample=b.dataset.familySample;familyUI()}
 if(b.dataset.shelf){if(!state.work.sample){toast('Select an element tile first.');return}state.work.assignments||={};state.work.assignments[state.work.sample]=b.dataset.shelf;state.work.sample=null;familyUI();save()}
 if(b.dataset.rank){state.work.order||=[];if(!state.work.order.includes(b.dataset.rank))state.work.order.push(b.dataset.rank);reactionUI();save()}
 if(b.dataset.explain){state.work.explanation=b.dataset.explain;reactionUI();save()}
 if(b.dataset.ion){const k=b.dataset.ion;state.work[k]=Math.max(0,Math.min(6,(state.work[k]||0)+Number(b.dataset.delta)));ionsUI();save()}
 if(b.dataset.compound){const r=validateCompound(b.dataset.compound);feedback(r.text,!r.ok);if(r.ok)$('#feedback').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-act="finish">Reconnect Element City</button></div>')}
});
document.addEventListener('change',e=>{if(e.target.id?.startsWith('practice-')){state.practiceDrafts||={};state.practiceDrafts[practiceId]||={};state.practiceDrafts[practiceId][e.target.id.slice(9)]=e.target.value;save()}if(e.target.dataset.identify){state.work.answers||={};state.work.answers[e.target.dataset.identify]=e.target.value;save()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.act){actions[b.dataset.act]?.();return}if(b.dataset.tool){actions[b.dataset.tool]?.();return}if(b.dataset.scan){state.work.scans=[...(state.work.scans||[]),b.dataset.scan];const mat=MATERIALS.find(x=>x.id===b.dataset.scan);record('Measured evidence · '+mat.name,`${mat.conductivity} conductivity; ${mat.bend.toLowerCase()}; ${mat.look.toLowerCase()}. Simulated observations.`);powerUI();beep();save()}if(b.dataset.material){state.work.reason=$('#power-reason')?.value;state.work.material=b.dataset.material;powerUI();save()}if(b.dataset.element)elementDetails(Number(b.dataset.element))});
document.addEventListener('input',e=>{if(e.target.id==='element-search'){const q=e.target.value.trim().toLowerCase();$$('[data-element]').forEach(b=>{const x=ELEMENTS[Number(b.dataset.element)-1];b.classList.toggle('dim',!!q&&!(x.name.toLowerCase().includes(q)||x.symbol.toLowerCase()===q||String(x.number)===q))})}if(e.target.id==='volume'){state.settings.volume=Number(e.target.value);$('#vol-label').textContent=Math.round(state.settings.volume*100)+'%';beep();save()}});
document.addEventListener('change',e=>{if(e.target.id==='reduced')state.settings.reducedMotion=e.target.checked;if(e.target.id==='show-touch')state.settings.touch=e.target.checked;if(e.target.id==='control-style'){state.settings.controlStyle=e.target.value;clearInputs()}if(e.target.id==='control-size')state.settings.controlSize=Number(e.target.value);if(e.target.id==='camera-sensitivity')state.settings.cameraSensitivity=Number(e.target.value);if(e.target.id==='auto-camera')state.settings.autoCamera=e.target.checked;if(e.target.id==='quality'){state.settings.quality=e.target.value;if(e.target.value!=='auto')world.applyQuality?.(e.target.value)}if(e.target.id==='guide-line')state.settings.guideLine=e.target.checked;if(e.target.id==='timer')state.settings.timer=e.target.checked;if(e.target.id==='power-reason')state.work.reason=e.target.value;sync();save()});
const motionKeys=['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','shift',' '];document.addEventListener('keydown',e=>{if(e.key==='Tab'&&modal){const items=$$('.dialog button:not(:disabled),.dialog input,.dialog select,.dialog a');if(items.length){const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.dialog'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(e.key==='Escape'){e.preventDefault();if(modal==='title')return;if(modal){if(modal==='table'&&returnTo==='mission')showMission();else if(modal==='table'&&returnTo==='practice')practiceUI(practiceId);else if(modal==='table'&&returnTo&&returnTo.startsWith?.('monitor:'))monitorUI(returnTo.slice(8));else state.started?closeModal():title()}else pause();return}if(modal||!state.started)return;const key=e.key.toLowerCase();if(e.metaKey||e.ctrlKey||e.altKey){clearInputs();return}if(motionKeys.includes(key)){e.preventDefault();allInputs.set('keyboard-'+e.key.toLowerCase(),e.key,true)}if(e.repeat)return;if(key==='e')world.toggleVehicle();if(key==='f')world.interact();if(key==='t')table();if(key==='n')notebook();if(key==='m')cityMap();if(key==='p')pause();if(key==='c')actions.camera();if(key==='r')actions.recenter()});document.addEventListener('keyup',e=>allInputs?.set('keyboard-'+e.key.toLowerCase(),e.key,false));const DEBUG=new URLSearchParams(location.search).has('debug');window.addEventListener('blur',()=>{clearInputs();if(state.started&&!modal&&!DEBUG)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.started){clearInputs();save();if(!modal&&!DEBUG)pause()}});function clearInputs(){tabletControls?.clear();allInputs?.clear();world?.setStick?.(0,0);for(const k of [...motionKeys,'up','down','left','right','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'])world.setInput(k,false);$$('[data-key]').forEach(b=>b.classList.remove('held'))}
allInputs=new InputMixer((key,held)=>world.setInput(key,held));tabletControls=attachTabletControls($('#touch'),()=>world,()=>state.started&&!modal,allInputs);$('#vehicle').onclick=()=>world.toggleVehicle();$('#interact').onclick=()=>world.interact();$('#pause').onclick=pause;$('#dispatch-btn').onclick=dispatch;window.addEventListener('pagehide',()=>{clearInputs();save()});
window.addEventListener('pageshow',e=>{clearInputs();if(e.persisted&&state.started&&!modal)pause()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)clearInputs()});
for(const t of ['gesturestart','gesturechange','gestureend'])document.addEventListener(t,e=>e.preventDefault(),{passive:false});
document.addEventListener('contextmenu',e=>{if(e.target.closest('#world,#touch'))e.preventDefault()});
document.addEventListener('dblclick',e=>{if(e.target.closest('#world,#touch'))e.preventDefault()},{passive:false});
document.addEventListener('change',e=>{const id=e.target.id;if(['mon-ph','mon-element','mon-fits'].includes(id)&&modal==='monitor'){const mid=$('[data-act="check-monitor"]')?.dataset.monitor;if(!mid)return;state.waterDraft||={};state.waterDraft[mid]||={};state.waterDraft[mid][id.slice(4)]=e.target.value;save()}});
Object.assign(actions,{
 water:waterIntro,
 'water-go':()=>{state.trackWater=true;closeModal();banner('SIDE JOB','Harbor Water Watch','Follow the gold route to the seawall');save()},
 'check-monitor':()=>{const id=$('[data-act="check-monitor"]').dataset.monitor,answer={ph:$('#mon-ph').value,element:$('#mon-element').value,fits:$('#mon-fits').value};const r=validateMonitor(id,answer);
   if(!r.ok){feedback(r.text,true);return}state.water||={};const first=!state.water[id];state.water[id]=true;record('Harbor Water Watch · '+MONITORS.find(m=>m.id===id).formula,r.text);feedback(r.text);
   if(first&&waterComplete(state.water)){state.trackWater=false;$('#feedback').insertAdjacentHTML('beforeend',`<p><b>Side job complete.</b> ${esc(WATER_DEBRIEF)}</p>`);banner('SIDE JOB COMPLETE','Harbor Water Watch','+75 REP','passed')}else if(first)toast('Reading logged. Next monitor marked on your route.');sync();save()},
 'monitor-hint':()=>{const id=$('[data-act="monitor-hint"]').dataset.monitor,m=MONITORS.find(x=>x.id===id),n=(state.hints['w-'+id]||0);state.hints['w-'+id]=n+1;
   $('#hint').textContent=[`Compare ${m.colorName.toLowerCase()} with the scale: is it below, near, or above pH 7?`,`Find ${m.element} on the table. Metals are to the left of the stair-step line; nonmetals to the right (hydrogen is a nonmetal).`,`Pattern: nonmetal oxide → acidic; soluble metal oxide → basic. If the evidence does not match, it is an exception.`][Math.min(n,2)];save()},
 'table-from-monitor':()=>{const id=$('[data-act="table-from-monitor"]').dataset.monitor;table('monitor:'+id)}
});
if(new URLSearchParams(location.search).has('debug'))window.__ec={get world(){return world},get state(){return state},actions,sync,save,clearInputs,get modal(){return modal}};title();sync();
